def ok(node):
    if node is None:
        return True
    key, left, right = node
    if left and left[0] > key:
        return False
    if right and right[0] < key:
        return False
    return ok(left) and ok(right)

def inorder(node):
    return inorder(node[1]) + [node[0]] + inorder(node[2]) if node else []

