import heapq
graph = {"A": [("C", 5), ("B", 1)], "B": [("D", 1)], "C": [("E", 1)], "D": [("C", 1)], "E": []}

def dijkstra(src):
    dist, pq = {src: 0}, [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if d + w < dist.get(v, float("inf")):
                dist[v] = d + w
                heapq.heappush(pq, (d + w, v))
    return dist
