graph = {1: [2, 3], 2: [4], 3: [4], 4: [1]}

def dfs(start):
    seen, stack, order = set(), [start], []
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        order.append(node)
        for nb in graph[node]:
            stack.append(nb)
    return order

